import {locationMarkup,mountLocations,locationValid} from './cleaning-locations.js';
import {mountList} from './cleaning-lists.js';
import {offline,compressPhoto} from './cleaning-offline.js';
const C=window.CHALEZINHO_CONFIG,app=document.querySelector('#app'),message=document.querySelector('#message'),nav=document.querySelector('#navigation'),appMode=document.body.dataset.cleaningApp||'gateway',adminPage=appMode==='admin'||location.pathname.endsWith('faxinas-admin.html');
const appPaths={owner:'/faxinas/contratar/',worker:'/faxinas/trabalhar/',admin:'/faxinas/administracao/'};
const returnPath=()=>appMode==='gateway'?'faxinas.html':appPaths[appMode].slice(1);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0)/100);
const dt=v=>v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'}).format(new Date(v)):'A confirmar';
const stateLabel={routine:'Rotina sugerida',requested:'Buscando profissional',awaiting_pix:'Aguardando Pix',confirmed:'Faxina confirmada',in_progress:'Limpeza em andamento',review:'Aguardando conferência',correction:'Correção solicitada',approved:'Faxina aprovada',cancelled:'Cancelada',refund_pending:'Devolução em análise',refunded:'Devolução confirmada'};
const payoutLabel={not_authorized:'Aguardando aprovação',authorized:'Repasse autorizado',processing:'Repasse processando',paid:'Repasse pago'};
const errors={invalid_city:'Escolha uma cidade brasileira da lista.',city_selection_required:'Há cidades com esse nome em mais de um estado. Escolha a cidade e o estado.',invalid_neighborhood:'Escolha um bairro da lista. Se não encontrar, peça a inclusão para conferência.',invalid_address:'Informe rua e número ou uma referência clara, com pelo menos cinco caracteres.',location_review_required:'Confira o bairro, informe a fonte e marque a confirmação.',neighborhood_already_exists:'Esse nome já aponta para um bairro cadastrado. Confira antes de incluir.',location_request_changed:'Esse pedido já foi analisado. Atualize a lista.',manual_pix_not_configured:'A administração ainda precisa cadastrar e liberar sua chave Pix.',invalid_manual_pix:'Confira o tipo de chave Pix, a chave e o nome que aparece no banco.',manual_statement_required:'Confira o lançamento no extrato, o valor, a data e o ID da transação.',bank_reference_already_used:'Esse ID do banco já foi registrado em outro pagamento. Confira antes de salvar.',payment_method_changed:'A forma de pagamento mudou. A administração precisa revisar as condições aceitas.',email_confirmation_required:'Confirme seu e-mail para entrar. Abra o link recebido ou peça um novo envio.',correction_photo_required:'Depois da correção, envie uma nova foto para mostrar o resultado.',execution_not_started:'Toque em Começar limpeza antes de terminar.',proposal_changed_reload:'O horário proposto mudou. Atualize a faxina antes de responder.',login_required:'Entre na sua conta para continuar.',pilot_not_released:'Seu interesse está registrado. Vamos avisar quando você puder usar os serviços.',cleaning_admin_required:'Esta área é exclusiva para administradores autorizados.',financial_dependency_unavailable:'O Pix das faxinas ainda aguarda liberação do PagBank. Nenhuma cobrança foi criada.',assisted_quote_required:'Precisamos conferir o imóvel para informar um preço. Peça ajuda à administração.',quote_changed_review:'O preço mudou. Confira os valores novamente antes de confirmar.',schedule_conflict:'Este horário coincide com outro serviço ou fica fora da sua disponibilidade.',service_unavailable:'Outra profissional pode ter aceitado ou o serviço não está mais disponível. Atualize a lista.',invalid_job_window:'O horário não permite terminar a limpeza. Escolha uma janela maior.',checklist_and_photos_required:'Marque todos os itens e envie as fotos pedidas antes de terminar.',incident_requires_review:'Há uma ocorrência ou alteração aberta. A administração precisa analisar.',configuration_changed_reload:'Outra pessoa alterou as regras. Atualize a tela antes de salvar.',start_not_allowed:'A faxina precisa estar confirmada e dentro do horário combinado para começar.',provider_reconciliation_required:'Estamos conferindo o pagamento com o PagBank. Não pague outra vez.',custody_release_homologation_required:'A liberação de valores aguarda homologação do PagBank.',invalid_photo:'Escolha uma foto válida da câmera ou galeria.',photo_too_large:'A foto ficou muito grande. Tente uma nova foto.',pms_link_not_authorized:'Seu acesso não permite vincular este imóvel ao PMS.',performed_service_required:'A avaliação fica disponível após a realização e aprovação da faxina.',receiver_verification_required:'O recebimento da profissional ainda precisa ser verificado.',registration_closed:'Os novos cadastros estão pausados. Tente mais tarde.'};
let sb,session,hub,bootstrap,view='home',activeJob,propertyDraft={},requestDraft={},adminTab=['participants','locations','receivers'].includes(new URLSearchParams(location.search).get('tab'))?new URLSearchParams(location.search).get('tab'):'participants';
function notice(text,error=false){message.textContent=text;message.className=error?'error':'';if(error)message.focus();}
function render(html,focus=true){app.innerHTML=html;app.setAttribute('aria-busy','false');if(focus){app.focus();scrollTo({top:0,behavior:'instant'});}bind();}
async function api(action,data={}){const token=(await sb?.auth.getSession())?.data?.session?.access_token;let response;try{response=await fetch(C.supabaseUrl+'/functions/v1/cleaning-platform',{method:'POST',headers:{'content-type':'application/json',apikey:C.supabaseKey,...(token?{authorization:'Bearer '+token}:{})},body:JSON.stringify({action,...data}),signal:AbortSignal.timeout(25000)});}catch{throw Error('network_error');}const body=await response.json().catch(()=>({ok:false,error:'unavailable'}));if(!response.ok||!body.ok)throw Error(body.error||'unavailable');return body;}
function errorText(e){return errors[e.message]||(e.message==='network_error'?'Sem conexão agora. Seus dados continuam aqui. Tente novamente.':e.message?.startsWith('invalid_')?'Confira os campos. Use valores positivos e preencha as informações pedidas.':'Não foi possível concluir. Confira as informações e tente novamente.');}
async function run(action,data={},done){try{notice('Salvando…');const r=await api(action,data);notice('Pronto. Salvo com segurança.');if(done)await done(r.result);else await load(view);return r.result;}catch(e){notice(errorText(e),true);return null;}}
function back(target='home'){return `<button class="quiet back" data-view="${target}">← Voltar</button>`;}
function heading(step,title,text){return `<div class="narrow">${back()}<p class="eyebrow">${step}</p><h1>${title}</h1>${text?`<p>${text}</p>`:''}`;}
function input(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function checked(label,name,value=false){return `<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;}
function options(list,current){return list.map(([value,label])=>`<option value="${esc(value)}" ${value===String(current)?'selected':''}>${esc(label)}</option>`).join('');}
function bind(){app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));app.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>job(b.dataset.job));app.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>session?profile(b.dataset.role):login(b.dataset.role));}
function menu(){nav.hidden=!session;if(!session)return;const items=adminPage?[['admin','⚙ Gestão'],['profile','👤 Conta']]:appMode==='worker'?[['home','⌂ Início'],['offers','✦ Serviços disponíveis'],['services','✓ Meus serviços'],['profile','👤 Perfil']]:appMode==='owner'?[['home','⌂ Início'],['services','✓ Minhas faxinas'],['properties','▦ Imóveis'],['directory','☆ Profissionais'],['profile','👤 Perfil']]:[['home','⌂ Aplicativos'],['profile','👤 Conta']];nav.innerHTML=items.map(([v,l])=>`<button data-menu="${v}" class="${view===v?'active':''}">${l}</button>`).join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>go(b.dataset.menu));}
function appChooser(){view='home';render(`<p class="eyebrow">VILLE FAXINAS</p><h1>Qual aplicativo você quer abrir?</h1><p>Seu acesso e seus cadastros são os mesmos. Cada aplicativo tem suas próprias telas.</p><div class="grid"><a class="choice app-choice" href="${appPaths.owner}"><span aria-hidden="true">⌂</span><strong>Quero contratar uma faxina</strong><small>Pedir, pagar e conferir a limpeza.</small></a><a class="choice app-choice worker-choice" href="${appPaths.worker}"><span aria-hidden="true">✦</span><strong>Quero trabalhar com faxinas</strong><small>Aceitar, realizar e acompanhar o recebimento.</small></a></div>${hub?.admin?`<a class="button spacer" href="${appPaths.admin}">⚙ Abrir administração</a>`:''}<p class="note spacer">Você pode usar os dois aplicativos com a mesma conta.</p>`);menu();}
function landing(){if(appMode==='gateway')return appChooser();if(adminPage){render(`<p class="eyebrow">ADMINISTRAÇÃO EXCLUSIVA</p><h1>Gestão das faxinas</h1><p>Entre com uma conta administrativa autorizada.</p><button id="admin-login" class="primary">Entrar na administração</button>`);app.querySelector('#admin-login').onclick=()=>login();return;}view='home';const worker=appMode==='worker';render(`<section class="hero"><span class="badge">${bootstrap?.settings.pilot?'Primeiros participantes · Guarapari':'Bem-vindo'}</span><p class="eyebrow">${worker?'APLICATIVO DA PROFISSIONAL':'APLICATIVO DO PROPRIETÁRIO'}</p><h1>${worker?'Seu trabalho.<br>Seu dia mais leve.':'Uma casa cuidada.<br>Uma rotina mais leve.'}</h1><p>${worker?'Confira os serviços disponíveis e quanto vai receber antes de aceitar.':'Peça sua faxina e acompanhe o pedido, o pagamento e a conferência.'}</p></section><button class="choice" data-role="${worker?'worker':'owner'}"><span aria-hidden="true">${worker?'✦':'⌂'}</span><strong>${worker?'Quero trabalhar com faxinas':'Quero contratar uma faxina'}</strong><small>${worker?'Cadastre sua região e disponibilidade.':'Informe seu imóvel e escolha o dia.'}</small></button><section class="card spacer"><h3>${worker?'Você decide quais serviços aceitar':'Preço claro, do começo ao fim'}</h3><p>${worker?'O valor líquido aparece antes do aceite. Não há volume de trabalho garantido.':'O preço considera área, quartos, banheiros e camas. Você confere escopo e taxas antes de solicitar.'}</p><div class="row wrap"><span class="small">${bootstrap?.settings.pilot?'Cadastros abertos. Serviços liberados por convite.':'Cadastro simples.'}</span>${worker?'':'<button data-view="prices" class="quiet">Ver preços sugeridos →</button>'}</div></section>`);menu();}
function prices(){const s=bootstrap.settings;render(`${heading('PREÇOS','Quanto custa uma faxina?','Valores sugeridos para limpeza padrão. A categoria precisa comportar área, quartos e banheiros ao mesmo tempo.')}<div class="card table"><table><thead><tr><th>Até m²</th><th>Quartos</th><th>Banheiros</th><th>Base</th></tr></thead><tbody>${s.categories.map(x=>`<tr><td>${x.area}</td><td>${x.rooms}</td><td>${x.bathrooms}</td><td>${money(x.cents)}</td></tr>`).join('')}</tbody></table><p class="small spacer">Acima dos limites ou sem metragem: orçamento assistido.</p></div><div class="card"><h3>${esc(s.service.name)}</h3><p>${esc(s.service.scope)}</p><p>Por quarto: até ${s.beds.double_included} cama(s) de casal ou ${s.beds.single_included} de solteiro. Em quarto misto, a franquia de casal vem primeiro. Cada cama extra: ${money(s.beds.extra_cents)}.</p></div></div>`);}
function login(role=appMode==='worker'?'worker':'owner',signup=false){view='login';render(`${heading('SUA CONTA',signup?'Vamos começar':'Bom ter você aqui','Use o mesmo acesso do Chalezinho Ville, se já tiver uma conta.')}<form id="login-form" class="card">${signup?input('Seu nome','name','','text','required autocomplete="name"')+input('Celular com DDD','phone','','tel','required autocomplete="tel"'):''}${input('E-mail','email','','email','required autocomplete="email"')}${input('Senha','password','','password',`required minlength="8" autocomplete="${signup?'new-password':'current-password'}"`)}<button class="primary">${signup?'Criar minha conta':'Entrar'}</button><button type="button" id="change-login" class="quiet">${signup?'Já tenho uma conta':'Ainda não tenho conta'}</button>${signup?'':'<a href="/auth.html?mode=recover&return=${encodeURIComponent(returnPath())}">Esqueci minha senha</a>'}</form></div>`);document.querySelector('#change-login').onclick=()=>login(role,!signup);document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const button=e.target.querySelector('button');button.disabled=true;try{let r;if(signup){r=await sb.auth.signUp({email:f.email,password:f.password,options:{data:{full_name:f.name,phone:f.phone,onboarding:'cleaning'},emailRedirectTo:location.origin+'/auth-callback.html?next='+encodeURIComponent(returnPath())}});}else r=await sb.auth.signInWithPassword({email:f.email,password:f.password});if(r.error)throw r.error;session=r.data.session;if(!session){confirmation(f.email,role);return;}sessionStorage.removeItem('cleaning_confirmation');await load('home',false);if(adminPage)go('admin');else if(!hub.member)profile(role,{name:f.name,phone:f.phone});else go('home');}catch(e){if(e.code==='email_not_confirmed'){confirmation(f.email,role);return;}notice(e.code==='over_email_send_rate_limit'||e.status===429?'Aguarde um pouco antes de pedir outro e-mail.':signup?'Não foi possível criar a conta. Confira os campos ou tente entrar se já tem cadastro.':'Não foi possível entrar. Confira o e-mail e a senha ou tente novamente.',true);}finally{button.disabled=false;}};}
function confirmation(email,role='owner'){
 view='confirmation';sessionStorage.setItem('cleaning_confirmation',JSON.stringify({email,role}));nav.hidden=true;
 render(`${heading('FALTA CONFIRMAR O E-MAIL','Abra seu e-mail para continuar','Enviamos um link de confirmação. Toque nele para ativar sua conta.')}<section class="card"><p><strong>${esc(email)}</strong></p><p>Confira também a pasta de spam. Seu celular foi informado no cadastro; ele ainda não foi verificado.</p><button id="confirmed-login" class="primary">Já confirmei meu e-mail · Entrar</button><button id="resend-confirmation">Enviar o e-mail de novo</button><button id="correct-email" class="quiet">Voltar e conferir o e-mail</button><p class="small">Se você já tinha uma conta confirmada, pode entrar com a mesma senha.</p></section></div>`);
 const enter=()=>{login(role);document.querySelector('[name=email]').value=email;};document.querySelector('#confirmed-login').onclick=enter;document.querySelector('#correct-email').onclick=enter;
 const b=document.querySelector('#resend-confirmation');const key='cleaning_resend:'+email.toLowerCase();
 const update=()=>{const left=Math.max(0,Math.ceil((Number(sessionStorage.getItem(key)||0)+60000-Date.now())/1000));b.disabled=left>0;b.textContent=left?`Novo envio em ${left}s`:'Enviar o e-mail de novo';if(left&&b.isConnected)setTimeout(update,1000);};update();
 b.onclick=async()=>{b.disabled=true;try{const {error}=await sb.auth.resend({type:'signup',email,options:{emailRedirectTo:location.origin+'/auth-callback.html?next='+encodeURIComponent(returnPath())}});if(error)throw error;sessionStorage.setItem(key,String(Date.now()));notice('Pedido de envio recebido. Confira seu e-mail e a pasta de spam.');update();}catch(e){notice(e.status===429||e.code==='over_email_send_rate_limit'?'Aguarde um pouco antes de pedir outro e-mail.':'Não foi possível enviar agora. Tente novamente.',true);b.disabled=false;}};
}
async function profile(role,initial={}){view='profile';const m=hub?.member||{},worker=appMode==='worker',manage=adminPage||appMode==='gateway';if(manage&&!hub?.member){render('<h1>Sua conta</h1><p>Escolha o aplicativo de contratar ou trabalhar para completar o cadastro correspondente.</p><a class="button" href="/faxinas.html">Ver aplicativos</a><button id="signout" class="quiet">Sair da conta</button>');document.querySelector('#signout').onclick=async()=>{await sb.auth.signOut();session=null;hub=null;activeJob=null;landing();menu();};menu();return;}render(`${heading('SUA CONTA',manage?'Seus dados':worker?'Seu perfil profissional':'Seus dados para contratar','Uma conta para os aplicativos Ville Faxinas.')}<form id="profile-form" class="card">${input('Seu nome','name',initial.name||m.name||session?.user?.user_metadata?.full_name||'','text','required autocomplete="name"')}${input('Celular com DDD','phone',initial.phone||m.phone||session?.user?.user_metadata?.phone||'','tel','required autocomplete="tel"')}${worker?`<div id="worker-fields">${locationMarkup({...m,city:m.city||'Guarapari'},true)}<fieldset><legend>Dias disponíveis</legend><div class="row wrap">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((d,i)=>`<label><input type="checkbox" name="day" value="${i}" ${m.availability?.days?.includes(i)||!m.availability?'checked':''}>${d}</label>`).join('')}</div></fieldset><div class="fields">${input('Começo','start',m.availability?.start||'08:00','time','required')}${input('Até','end',m.availability?.end||'18:00','time','required')}</div>${checked('Aceito limpeza padrão','standard',m.services?.includes('standard')||!m.services)}<p class="small">Foto e apresentação são opcionais. Dados para recebimento serão pedidos antes dos serviços reais.</p></div>`:''}<button class="primary">Salvar e continuar</button></form><button id="signout" class="quiet">Sair da conta</button></div>`);const f=document.querySelector('#profile-form');f.onsubmit=e=>{e.preventDefault();if(worker&&!locationValid(f,true)){notice('Escolha uma cidade da lista e pelo menos um bairro onde atende.',true);return;}const v=Object.fromEntries(new FormData(f));run('member',{name:v.name,phone:v.phone,owner:appMode==='owner'||!!m.owner,worker:worker||!!m.worker,city:worker?v.city:m.city,city_ibge:worker?Number(v.city_ibge):m.city_ibge,bairros:worker?[...f.querySelectorAll('[name=bairros]:checked')].map(x=>x.value):m.bairros,services:worker?(v.standard?['standard']:[]):m.services,availability:worker?{days:[...f.querySelectorAll('[name=day]:checked')].map(x=>Number(x.value)),start:v.start,end:v.end}:m.availability},()=>load(adminPage?'admin':'home'));};document.querySelector('#signout').onclick=async()=>{await sb.auth.signOut();session=null;hub=null;activeJob=null;nav.hidden=true;notice('Você saiu da conta.');landing();};if(worker){manualReceiverProfile(m);await mountLocations(f,{api,initial:{...m,city:m.city||'Guarapari'},multiple:true,notice});}menu();}
async function manualReceiverProfile(m){if(!m.worker||!m.worker_approved||hub.payment_method!=='manual_pix')return;const receiver=hub.manual?.receiver;const box=document.createElement('section');box.className='card';const anchor=document.querySelector('#signout');if(!anchor)return;anchor.before(box);try{const {receiverFields}=await import('./cleaning-manual.js');if(!box.isConnected||view!=='profile')return;box.innerHTML=`<h3>Seu Pix para receber</h3><p>${receiver?.verified?'Chave conferida pela administração.':'A administração precisa conferir o titular e a chave antes dos pagamentos.'}</p><form id="manual-receiver-profile">${receiverFields(receiver,{input,options})}<button class="primary">Salvar minha chave Pix</button></form><p class="small">Informar sua chave não confirma um repasse. Sua chave é privada, visível para você e administradores autorizados.</p>`;box.querySelector('form').onsubmit=e=>{e.preventDefault();run('manual_receiver',Object.fromEntries(new FormData(e.target)),()=>load('profile'));};}catch{box.innerHTML='<p>Não foi possível abrir seus dados de recebimento. Tente novamente ao entrar no perfil.</p>';}}
function personalJobs(){return hub.jobs.filter(j=>!j.is_test&&(appMode==='worker'?j.worker_id===session.user.id:appMode==='owner'?j.owner_id===session.user.id:j.owner_id===session.user.id||j.worker_id===session.user.id));}
function ownRequestNote(){const jobs=hub.jobs.filter(j=>!j.is_test&&j.owner_id===session.user.id&&['requested','awaiting_pix'].includes(j.state));return jobs.length?`<section class="card own-requests"><h2>Seus pedidos como proprietário</h2><p class="note">Você tem ${jobs.length} pedido(s) como proprietário. Sua conta não pode aceitar o próprio pedido. Para testar o aceite, entre com outra conta profissional aprovada e liberada.</p>${jobs.slice(0,3).map(j=>`<article class="own-request" data-own-request="${esc(j.id)}"><div class="row wrap"><strong>${esc(j.property_name||'Faxina')}</strong><span class="badge">Pedido seu</span></div><p class="time">${dt(j.starts_at)} até ${dt(j.ends_at)}</p><p>${esc(stateLabel[j.state])}</p><p>${j.state==='awaiting_pix'?'Outra profissional já aceitou. Confira o pagamento no aplicativo de contratar.':'Este pedido aguarda outra profissional. Ele não entra nas ofertas que você pode aceitar.'}</p><a class="button" href="${appPaths.owner}?job=${encodeURIComponent(j.id)}">Ver meu pedido</a></article>`).join('')}${jobs.length>3?`<a class="button" href="${appPaths.owner}">Ver todos os meus pedidos</a>`:''}</section>`:'';}
function home(){if(appMode==='gateway')return appChooser();if(adminPage)return go('admin');if(!hub.member)return landing();if((appMode==='owner'&&!hub.member.owner)||(appMode==='worker'&&!hub.member.worker))return profile(appMode);view='home';const m=hub.member,ownerApp=appMode==='owner',pilot=hub.configuration.settings.pilot;render(`<p class="eyebrow">SEU DIA MAIS LEVE</p><h1>Olá, ${esc(m.name.split(' ')[0])}.</h1>${pilot&&(ownerApp?!m.owner_released:(!m.worker_released||!m.worker_approved))?'<p class="note warning">Seu interesse está registrado. Estamos liberando os primeiros participantes. Você já pode completar seu cadastro neste aplicativo.</p>':''}${m.blocked?'<p class="note warning">Novos serviços estão pausados para sua conta. Consulte a administração.</p>':''}${!ownerApp?ownRequestNote():''}<div class="grid">${ownerApp?`<button class="choice" data-view="request"><span aria-hidden="true">＋</span><strong>Pedir uma faxina</strong><small>Escolha o dia e confira o preço.</small></button>`:''}${!ownerApp?`<button class="choice" data-view="offers"><span aria-hidden="true">✦</span><strong>Encontrar serviços</strong><small>${hub.offers.length} serviço(s) disponível(is) na sua região.</small></button>`:''}</div><section class="spacer"><div class="row wrap"><h2>${ownerApp?'Suas faxinas':'Seus serviços'}</h2><button data-view="services" class="quiet">Ver todas →</button></div>${personalJobs().filter(j=>!['cancelled','refunded','approved'].includes(j.state)).slice(0,4).map(jobCard).join('')||'<p class="empty">Quando houver uma faxina, ela vai aparecer aqui.</p>'}</section>${ownerApp?`<section class="card"><div class="row wrap directory-heading"><h3>Profissionais</h3><button data-view="directory" class="quiet">Ver profissionais →</button></div>${hub.directory.slice(0,4).map(w=>`<div class="row wrap"><p><strong>${esc(w.name)}</strong><br><small>${w.count?'☆ '+w.mean+' · '+w.count+' avaliação(ões)':'Ainda sem avaliações'}</small></p><button data-directory-favorite="${w.user_id}">${hub.favorites.includes(w.user_id)?'★ Favorita':'☆ Favoritar'}</button></div>`).join('')||'<p>As profissionais aprovadas aparecerão aqui.</p>'}</section>`:''}${hub.notifications.length?`<section class="card"><h3>Últimos avisos</h3>${hub.notifications.slice(0,3).map(n=>`<p>${esc(n.message)}<br><small>${dt(n.created_at)}</small></p>`).join('')}</section>`:''}`);app.querySelectorAll('[data-directory-favorite]').forEach(b=>b.onclick=()=>run('favorite',{worker_id:b.dataset.directoryFavorite,remove:hub.favorites.includes(b.dataset.directoryFavorite)},()=>load('home')));menu();}
function jobCard(j){const own=appMode!=='worker'&&j.owner_id===session.user.id;return `<section class="card"><div class="row wrap"><strong>${esc(j.property_name||'Faxina')}</strong><span class="badge">${stateLabel[j.state]}</span></div><p class="time spacer">${dt(j.starts_at)}</p><p>${esc(j.bairro||'')} · ${j.duration_minutes} minutos previstos</p>${j.change_pending?'<p class="note warning">Há uma mudança para revisar com a administração.</p>':''}${j.window_conflict?'<p class="note warning">A janela é curta. Ajuste antes de contratar.</p>':''}<div class="row wrap"><strong>${j.snapshot.quote_required?'Orçamento':money(own?j.snapshot.owner_total_cents:j.snapshot.worker_net_cents)}</strong>${appMode==='worker'?'<span>Você vai receber</span>':''}<button data-job="${j.id}">Ver faxina →</button></div></section>`;}
function services(){view='services';const jobs=personalJobs();render(`<div class="row wrap"><h1>${appMode==='worker'?'Meus serviços':'Suas faxinas'}</h1>${appMode==='owner'&&hub.member?.owner?'<button data-view="request">＋ Pedir uma faxina</button>':''}</div><p>Seus pedidos e os serviços atribuídos a você. Acompanhe a limpeza e a conferência.</p>${jobs.map(jobCard).join('')}`);const nodes=[...app.querySelectorAll('.card')];mountList(app,{id:'services',label:'Faxinas',scope:session.user.id,compact:false,empty:appMode==='worker'?'Você ainda não aceitou serviços. Consulte Serviços disponíveis.':'Nenhum pedido enviado por enquanto. Ao concluir a solicitação, sua faxina aparecerá aqui.',filters:[{value:'active',label:'Em andamento'},{value:'closed',label:'Encerradas'}],records:jobs.map((j,i)=>({node:nodes[i],key:j.id,title:j.property_name,subtitle:dt(j.starts_at),search:[j.bairro,stateLabel[j.state]],tags:[['approved','cancelled','refunded'].includes(j.state)?'closed':'active']}))});menu();}
function directory(){view='directory';render(`<h1>Profissionais</h1><p>Encontre profissionais e marque suas favoritas para os próximos pedidos.</p>${hub.directory.map(w=>`<section class="card"><div class="row wrap"><p><strong>${esc(w.name)}</strong><br><small>${esc(w.city||'')} · ${w.count?'☆ '+w.mean+' · '+w.count+' avaliação(ões)':'Ainda sem avaliações'}</small></p><button data-directory-favorite="${w.user_id}">${hub.favorites.includes(w.user_id)?'★ Favorita':'☆ Favoritar'}</button></div></section>`).join('')}`);const nodes=[...app.querySelectorAll('.card')];mountList(app,{id:'directory',label:'Profissionais',scope:session.user.id,compact:false,empty:'As profissionais aprovadas aparecerão aqui.',filters:[{value:'favorite',label:'Suas favoritas'}],records:hub.directory.map((w,i)=>({node:nodes[i],key:w.user_id,title:w.name,search:[w.city,...(w.bairros||[])],tags:hub.favorites.includes(w.user_id)?['favorite']:[]}))});app.querySelectorAll('[data-directory-favorite]').forEach(b=>b.onclick=()=>run('favorite',{worker_id:b.dataset.directoryFavorite,remove:hub.favorites.includes(b.dataset.directoryFavorite)},()=>load('directory')));menu();}
function properties(){view='properties';render(`<div class="row wrap"><h1>Seus imóveis</h1><button id="new-property">＋ Cadastrar imóvel</button></div><p>As informações ficam salvas para os próximos pedidos. Seus imóveis autorizados no PMS carregam aqui automaticamente.</p>${hub.properties.map(p=>`<section class="card" data-owner-property="${p.id}"><h3>${esc(p.name)}</h3>${p.pms_property_id?'<span class="badge">Vinculado ao PMS</span>':''}${p.pms_import_pending?'<p class="note">Complete endereço, quartos, banheiros e camas para pedir a faxina. Não há preço confirmado ainda.</p>':''}<p>${esc(p.bairro)} · ${p.area?`${p.area} m²`:'Metragem a conferir'} · ${p.rooms??'A conferir'} quarto(s) · ${p.bathrooms??'A conferir'} banheiro(s)</p><button data-edit-property="${p.id}">${p.pms_import_pending?'Completar':'Editar'}</button></section>`).join('')||''}`);document.querySelector('#new-property').onclick=()=>propertyForm();app.querySelectorAll('[data-edit-property]').forEach(b=>b.onclick=()=>propertyForm(hub.properties.find(x=>x.id===b.dataset.editProperty)));const nodes=[...app.querySelectorAll('[data-owner-property]')];mountList(app,{id:'properties',label:'Imóveis',scope:session.user.id,action:'Ver imóvel',empty:'Cadastre seu primeiro imóvel em duas etapas curtas.',filters:[{value:'pms',label:'Vinculados ao PMS'},{value:'pending',label:'Dados a completar'}],records:hub.properties.map((p,i)=>({node:nodes[i],primaryAction:nodes[i].querySelector('[data-edit-property]'),key:p.id,title:p.name,subtitle:[p.city,p.bairro].filter(Boolean).join(' · '),tags:[p.pms_property_id?'pms':'',p.pms_import_pending?'pending':''],badges:[p.pms_import_pending?'Completar dados':p.area?p.area+' m²':'Metragem a conferir',p.pms_property_id?'PMS':''].filter(Boolean)}))});menu();}
async function propertyForm(existing,step=1){view='properties';if(step===1){propertyDraft=existing?{...existing,...existing.access}:await offline('get','property:'+session.user.id).catch(()=>null)||{};}
 const p=propertyDraft;
 render(`${heading(`IMÓVEL · ETAPA ${step} DE 2`,step===1?'Qual é o imóvel?':'Como ele é por dentro?','Não precisa enviar fotos. Você pode completar instruções de acesso depois.')}<div class="progress"><span style="width:${step*50}%"></span></div><form id="property-form" class="card">${step===1?`${input('Nome para você reconhecer','name',p.name,'text','required placeholder="Ex.: Chalé Signature"')}<label>Tipo<select name="type">${options([['apartment','Apartamento'],['house','Casa'],['chalet','Chalé'],['other','Outro']],p.type||'chalet')}</select></label>${locationMarkup({...p,city:p.city||(p.pms_import_pending?'':'Guarapari')})}${input('Endereço completo','address',p.address,'text','required minlength="5" maxlength="500" autocomplete="street-address"')}<button class="primary">Continuar →</button>`:`${input('Área aproximada em m²','area',p.area,'number','min="1" step="0.1"')}${checked('Não sei a área','unknown',!p.area)}<div class="fields">${input('Quartos','rooms',p.rooms??(p.pms_import_pending?'':1),'number','required min="0" max="100"')}${input('Banheiros','bathrooms',p.bathrooms??(p.pms_import_pending?'':1),'number','required min="0" max="100"')}</div><fieldset><legend>Camas em cada quarto</legend><div id="beds"></div></fieldset><details><summary>Outros ambientes e materiais disponíveis</summary><fieldset><legend>Ambientes</legend>${['Sala','Cozinha','Varanda','Área externa','Piscina / spa'].map(x=>checked(x,'environment',p.environments?.includes(x)).replace('name="environment"',`name="environment" value="${x}"`)).join('')}</fieldset><fieldset><legend>Produtos e equipamentos</legend>${['Produtos de limpeza','Vassoura','Rodo','Balde','Aspirador','Enxoval limpo'].map(x=>checked(x,'supply',p.supplies?.includes(x)).replace('name="supply"',`name="supply" value="${x}"`)).join('')}</fieldset></details><details><summary>Acesso e cuidados (opcional agora)</summary><label>Como entrar<textarea name="instructions">${esc(p.instructions||'')}</textarea></label><label>Cuidados especiais<textarea name="care">${esc(p.care||'')}</textarea></label></details><button class="primary">Salvar imóvel</button><button type="button" id="property-back" class="quiet">← Voltar à primeira etapa</button>`}</form></div>`);
 const f=document.querySelector('#property-form');
 const persist=async()=>{const values=Object.fromEntries(new FormData(f));propertyDraft={...propertyDraft,...values};if(step===2){propertyDraft.area=f.elements.unknown.checked?null:values.area;propertyDraft.beds=[...app.querySelectorAll('[data-room]')].map(box=>Object.fromEntries([...box.querySelectorAll('input')].map(x=>[x.dataset.type,Number(x.value||0)])));propertyDraft.environments=[...f.querySelectorAll('[name=environment]:checked')].map(x=>x.value);propertyDraft.supplies=[...f.querySelectorAll('[name=supply]:checked')].map(x=>x.value);}const {instructions,care,access,...safe}=propertyDraft;await offline('put','property:'+session.user.id,safe).catch(()=>{});};
 if(step===2){const drawBeds=()=>{const count=Math.min(100,Math.max(0,Number(f.elements.rooms.value)));const prior=[...app.querySelectorAll('[data-room]')].map(b=>Object.fromEntries([...b.querySelectorAll('input')].map(x=>[x.dataset.type,x.value])));document.querySelector('#beds').innerHTML=Array.from({length:count},(_,i)=>`<div data-room="${i}" class="card"><strong>Quarto ${i+1}</strong><div class="fields">${bootstrap.settings.beds.types.map(t=>input(t.label,`bed_${i}_${t.id}`,prior[i]?.[t.id]??p.beds?.[i]?.[t.id]??(p.pms_import_pending?0:t.id===bootstrap.settings.beds.double_type?1:0),'number',`min="0" max="100" data-type="${esc(t.id)}"`)).join('')}</div></div>`).join('')};drawBeds();f.elements.rooms.onchange=drawBeds;const area=()=>f.elements.area.disabled=f.elements.unknown.checked;f.elements.unknown.onchange=area;area();document.querySelector('#property-back').onclick=async()=>{await persist();propertyForm(propertyDraft,1);};}
 f.oninput=()=>persist();f.onsubmit=async e=>{e.preventDefault();if(step===1&&!locationValid(f)){notice('Escolha uma cidade e um bairro da lista para continuar.',true);return;}await persist();if(step===1){propertyForm(null,2);return;}const saved=await run('property',{...propertyDraft,rooms:Number(propertyDraft.rooms),bathrooms:Number(propertyDraft.bathrooms),area:propertyDraft.area?Number(propertyDraft.area):null},()=>load('properties'));if(saved)await offline('delete','property:'+session.user.id);};if(step===1)await mountLocations(f,{api,initial:{...p,city:p.city||(p.pms_import_pending?'':'Guarapari')},notice});}
async function requestForm(propId,step=1){view='request';if(!hub.member?.owner){profile('owner');return;}if(!hub.properties.length){properties();notice('Cadastre seu primeiro imóvel para pedir uma faxina.');return;}if(step===1){requestDraft=await offline('get','request:'+session.user.id).catch(()=>null)||{};if(propId)requestDraft.property_id=propId;if(hub.properties.length===1){requestDraft.property_id=hub.properties[0].id;if(hub.properties[0].pms_import_pending){await propertyForm(hub.properties[0]);notice('Seu imóvel veio do PMS. Complete os dados da faxina uma vez para continuar.');return;}}}
 const r=requestDraft,s=hub.configuration.settings;
 if(step===1){render(`${heading('PEDIR FAXINA · ETAPA 1 DE 2','Quando você precisa?','Escolha uma janela em que a profissional consiga limpar o imóvel.')}<form id="request-form" class="card">${hub.properties.length===1?`<p>Imóvel: <strong>${esc(hub.properties[0].name)}</strong></p><input type="hidden" name="property_id" value="${hub.properties[0].id}">`:`<label>Imóvel<select name="property_id" required><option value="">Escolha seu imóvel</option>${hub.properties.map(p=>`<option value="${p.id}" ${p.id===r.property_id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`}${input('Dia','date',r.date,'date','required')}${input('Pode começar às','time',r.time||'09:00','time','required')}${input('Precisa terminar até','until',r.until||'13:00','time','required')}<label>Quem você prefere?<select name="target_worker"><option value="">Oferecer às profissionais aprovadas</option>${hub.directory.filter(x=>hub.favorites.includes(x.user_id)).map(x=>`<option value="${x.user_id}" ${r.target_worker===x.user_id?'selected':''}>${esc(x.name)} · favorita</option>`).join('')}</select></label>${s.addons.length?`<fieldset><legend>Serviços adicionais</legend>${s.addons.map(x=>`<label class="check"><input type="checkbox" name="addon" value="${x.id}" ${r.addons?.includes(x.id)?'checked':''}>${esc(x.label)} · ${money(x.cents)}</label>`).join('')}</fieldset>`:''}<button class="primary">Conferir preço →</button></form></div>`);const f=document.querySelector('#request-form');f.oninput=async()=>{requestDraft={...requestDraft,...Object.fromEntries(new FormData(f)),addons:[...f.querySelectorAll('[name=addon]:checked')].map(x=>x.value)};await offline('put','request:'+session.user.id,requestDraft).catch(()=>{});};f.onsubmit=async e=>{e.preventDefault();requestDraft={...requestDraft,...Object.fromEntries(new FormData(f)),addons:[...f.querySelectorAll('[name=addon]:checked')].map(x=>x.value)};requestForm(null,2);};return;}
 try{const q=(await api('quote',{property_id:r.property_id,worker_id:r.target_worker||undefined,addons:r.addons||[]})).result;const p=hub.properties.find(x=>x.id===r.property_id);if(q.reason==='incomplete_property'){await propertyForm(p);notice('Complete os dados da faxina uma vez para conferir o preço.');return;}if(q.quote_required){render(`${heading('ORÇAMENTO ASSISTIDO','Vamos conferir o tamanho','Sem metragem ou acima dos limites, o preço precisa de análise.')}<div class="card"><p>${esc(p.name)}</p><p>A administração já consegue consultar este imóvel. Complete a metragem, se souber, ou aguarde um orçamento.</p><button data-view="properties" class="primary">Ver meus imóveis</button></div></div>`);return;}
 render(`${heading('PEDIR FAXINA · ETAPA 2 DE 2','Confira sua faxina',p.name)}<section class="card"><p class="time">${esc(r.date.split('-').reverse().join('/'))} · ${esc(r.time)} até ${esc(r.until)}</p>${breakdown(q)}${q.addon_details?.length?`<p class="spacer"><strong>Adicionais escolhidos:</strong><br>${q.addon_details.map(a=>esc(a.label)+(appMode==='worker'?'':' · '+money(a.cents))+(a.scope?' — '+esc(a.scope):'')).join('<br>')}</p>`:''}<h3 class="spacer">${esc(q.service.name)}</h3><p class="scope">${esc(q.service.scope)}</p><p>Trocar e arrumar o enxoval: ${q.service.linen_change?'incluído, com enxoval limpo disponível':'não incluído'}. Lavagem de enxoval é separada.</p><details><summary>Condições do serviço</summary><p>${esc(q.terms)}</p><small>Versão ${esc(q.terms_version)}</small></details><form id="confirm-request">${checked('Li o preço, o escopo e as condições','accept_terms')}<p class="small">Depois do aceite da profissional, você paga por Pix. ${q.conditions.payment_method==='manual_pix'?'A administração confere o crédito no extrato antes de confirmar a faxina. O repasse à profissional será manual, após a conferência da limpeza.':'A faxina só fica confirmada após o PagBank confirmar o pagamento.'}</p>${!hub.financial_ready?`<p class="note warning">${hub.payment_method==='manual_pix'?'A chave Pix da administração ainda precisa ser cadastrada e liberada.':'O Pix das faxinas aguarda liberação.'} Você pode registrar o pedido; ainda não será possível confirmar a execução.</p>`:''}<button class="primary">Solicitar faxina</button><button type="button" id="request-back" class="quiet">← Ajustar dia ou horário</button></form></section></div>`);document.querySelector('#request-back').onclick=()=>requestForm(null,1);document.querySelector('#confirm-request').onsubmit=async e=>{e.preventDefault();if(!e.target.elements.accept_terms.checked){notice('Leia e marque o aceite das condições para continuar.',true);return;}const starts_at=new Date(r.date+'T'+r.time+':00-03:00').toISOString(),ends_at=new Date(r.date+'T'+r.until+':00-03:00').toISOString();requestDraft.request_key||=crypto.randomUUID();await offline('put','request:'+session.user.id,requestDraft);const saved=await run('request',{property_id:r.property_id,target_worker:r.target_worker||undefined,starts_at,ends_at,addons:r.addons||[],request_key:requestDraft.request_key,accept_terms:true,accepted_quote:q},async j=>{await offline('delete','request:'+session.user.id);await load('services',false);await job(j.id);});};}catch(e){notice(errorText(e),true);}}
function breakdown(q){return `<dl class="breakdown"><div><dt>Limpeza padrão</dt><dd>${money(q.base_cents)}</dd></div><div><dt>Camas extras (${q.extra_beds})</dt><dd>${money(q.beds_cents)}</dd></div><div><dt>Adicionais</dt><dd>${money(q.addons_cents)}</dd></div><div><dt>Valor do serviço</dt><dd>${money(q.service_cents)}</dd></div><div><dt>Taxa do proprietário</dt><dd>${money(q.owner_fee_cents)}</dd></div><div class="total"><dt>Total a pagar</dt><dd>${money(q.owner_total_cents)}</dd></div></dl>`;}
function offers(){view='offers';render(`${back()}<h1>Serviços disponíveis</h1>${ownRequestNote()}<p>Você decide se quer aceitar. O valor abaixo é o seu recebimento líquido. Não há volume de trabalho garantido.</p>${hub.offers.map(o=>`<section class="card"><span class="badge">${esc(o.bairro)} · ${esc(o.city)}</span><h3 class="spacer">${o.rooms} quarto(s), ${o.bathrooms} banheiro(s)${o.area?` · ${o.area} m²`:''}</h3><p class="time">${dt(o.starts_at)}<br>Prazo: ${dt(o.ends_at)}</p><p>${o.duration_minutes} minutos de trabalho previstos</p><p class="small">Camas: ${o.beds.map((b,i)=>'quarto '+(i+1)+' — '+bootstrap.settings.beds.types.map(t=>(b[t.id]||0)+' '+t.label.toLowerCase()).join(', ')).join('; ')}</p><p>${esc(o.scope)}</p>${o.addon_details?.length?`<p><strong>Adicionais pedidos:</strong><br>${o.addon_details.map(a=>esc(a.label)+(a.scope?' — '+esc(a.scope):'')).join('<br>')}</p>`:''}<p class="small">Materiais disponíveis: ${esc(o.supplies?.join(', ')||'A conferir com o proprietário')}</p><p class="price">${money(o.net_cents)}</p><p>Você vai receber este valor líquido. ${o.payment_method==='manual_pix'?'O pagamento é conferido pela administração; o repasse será feito por Pix após a conferência da limpeza. ':''}O endereço será mostrado após a confirmação do Pix.</p><button class="primary" data-accept="${o.id}">Aceitar este serviço</button></section>`).join('')||'<p class="note">Ainda não há serviços liberados para você. Confira seus bairros e disponibilidade no perfil.</p>'}`);app.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>{const o=hub.offers.find(x=>x.id===b.dataset.accept);run('accept',{job_id:o.id,expected_net_cents:o.net_cents},j=>job(j.id));});menu();}
async function job(id){view='services';try{const d=await api('job',{job_id:id});if((appMode==='owner'&&d.job.owner_id!==session.user.id)||(appMode==='worker'&&d.job.worker_id!==session.user.id))throw Error('job_not_found');activeJob=d;const j=d.job,own=j.owner_id===session.user.id,work=j.worker_id===session.user.id,checklist=j.snapshot.service?.checklist||[],hasRating=d.ratings.some(x=>x.author_id===session.user.id);render(`${back('services')}<div class="row wrap"><span class="eyebrow">SUA FAXINA</span><span class="badge">${stateLabel[j.state]}</span></div><h1>${esc(d.property.name)}</h1>${d.worker_name?`<p>Profissional: <strong>${esc(d.worker_name)}</strong></p>`:''}<p class="time">${dt(j.starts_at)} até ${dt(j.ends_at)}</p>${j.change_pending?`<p class="note warning">${j.change_pending.reason==='schedule_proposal'?'Novo horário proposto: '+dt(j.change_pending.starts_at)+' até '+dt(j.change_pending.ends_at)+'. Os dois lados precisam concordar.':'Houve uma mudança na rotina. Combine os próximos passos com a administração antes de começar.'}</p>${j.change_pending.reason==='schedule_proposal'?'<button id="accept-change" class="primary">Concordo com o novo horário</button><button id="decline-change">Não posso neste horário</button>':''}`:''}${j.is_test?'<p class="note warning">Serviço de teste. Não representa operação real.</p>':''}<div class="split"><section><div class="card">${own?breakdown(j.snapshot):`<h3>Você vai receber</h3><p class="price">${money(j.snapshot.worker_net_cents)}</p><p>Valor líquido combinado para este serviço.</p>`}<h3 class="spacer">O que está combinado</h3><p>${esc(j.snapshot.service?.scope||'Orçamento a conferir')}</p>${j.snapshot.addon_details?.length?`<p>Adicionais: ${j.snapshot.addon_details.map(a=>esc(a.label)+(appMode==='worker'?'':' · '+money(a.cents))+(a.scope?' — '+esc(a.scope):'')).join('; ')}</p>`:''}${j.snapshot.service?`<p class="small">Trocar enxoval: ${j.snapshot.service.linen_change?'incluído, com peças limpas fornecidas':'não incluído'}. Lavar enxoval é separado.</p>`:''}${j.snapshot.terms?`<details><summary>Condições aceitas</summary><p>${esc(j.snapshot.terms)}</p><small>Versão ${esc(j.snapshot.terms_version)}</small></details>`:''}</div>${d.access?`<div class="card"><h3>Onde fazer a limpeza</h3><p>${esc(d.access.address)}</p><p>${esc(d.access.instructions||'Instruções de acesso ainda não preenchidas.')}</p><p>${esc(d.access.care)}</p><small>Dados privados, apenas para os envolvidos neste serviço.</small></div>`:`<div class="card"><h3>${esc(d.property.bairro)} · ${esc(d.property.city)}</h3><p>O endereço completo fica disponível após confirmar o pagamento.</p></div>`}</section><section><div class="card"><h3>Próximo passo</h3>${nextStep(j,own,work,d.payment,d.manual_payment)}${j.state==='approved'?`<h3 class="spacer">${payoutLabel[j.payout]}</h3><p>${j.payout==='paid'?(j.snapshot.conditions?.payment_method==='manual_pix'?'Repasse registrado pela administração após conferir a transferência no banco.':'Recebimento confirmado.'):(j.snapshot.conditions?.payment_method==='manual_pix'?'Repasse autorizado. A administração fará o Pix e registrará a transferência aqui.':'Aprovar a faxina autoriza o repasse. O recebimento depende da confirmação do intermediador.')}</p><p class="small">${j.payout_paid_at?'Pix registrado: '+dt(j.payout_paid_at):j.payout_expected_at?(j.payout==='paid'?'Previsão informada: ':'Previsão de recebimento: ')+dt(j.payout_expected_at):'Previsão de recebimento ainda não confirmada.'}</p>`:''}<div id="pending"></div></div>${own&&['approved','refunded','cancelled'].includes(j.state)?`<button id="repeat" class="primary">Pedir outra faxina neste imóvel</button>`:''}</section></div>${work&&['in_progress','correction'].includes(j.state)?`<section class="spacer"><h2>Vamos deixar tudo pronto</h2><p>Marque os itens e envie as fotos pedidas. Cada confirmação fica salva.</p>${checklist.map((item,i)=>`<article class="card photo-card"><div class="row"><span class="step-number">${i+1}</span><h3>${esc(item.label)}</h3></div><label class="check"><input data-check="${i}" type="checkbox" ${d.results.some(x=>x.item===i&&x.result)?'checked':''}>Concluído</label>${photoMarkup(d.photos.filter(x=>x.item===i))}${item.photo?'<p class="small">Foto obrigatória para este item.</p>':''}<label>Enviar foto da galeria<input data-photo="${i}" type="file" accept="image/*"></label><label>Tirar foto agora<input data-photo="${i}" type="file" accept="image/*" capture="environment"></label><div data-preview="${i}"></div></article>`).join('')}<button class="primary" id="finish">✓ Terminei a limpeza</button><p class="small">A conclusão exige checklist e fotos salvos no servidor.</p></section>`:`<section class="spacer"><h2>Fotos e conferência</h2>${checklist.map((item,i)=>`<article class="card"><h3>${esc(item.label)}</h3><p class="small">${d.results.some(x=>x.item===i&&x.result)?'✓ Item concluído':'Aguardando conclusão'}</p>${photoMarkup(d.photos.filter(x=>x.item===i))}</article>`).join('')||'<p>As fotos vão aparecer aqui.</p>'}</section>`}<section class="card spacer"><h3>Precisou de ajuda?</h3><button id="problem">⚑ Relatar problema</button>${!['approved','cancelled','refunded'].includes(j.state)?'<button id="cancel" class="quiet">Pedir cancelamento</button>':''}${work?'<button id="favorite-toggle" class="quiet" hidden>Favorita</button>':''}${own&&j.worker_id?'<button id="favorite-toggle" class="quiet">☆ Marcar profissional favorita</button>':''}</section>${['awaiting_pix','confirmed','correction'].includes(j.state)?'<button id="change-time" class="spacer">Propor outro horário</button><div id="change-form"></div>':''}<div id="incident-form"></div>${d.incidents.length?`<section><h2>Ocorrências</h2>${d.incidents.map(i=>`<div class="card"><span class="badge ${i.state==='open'?'warning':''}">${i.state==='open'?'Em análise':'Analisada'}</span><p class="spacer">${esc(i.description)}</p><p class="small">Prazo de análise: ${dt(i.due_at)}</p>${i.messages.map(m=>`<p>${esc(m.body)}<br><small>${dt(m.created_at)}</small></p>`).join('')}${i.resolution?`<p><strong>Resolução:</strong> ${esc(i.resolution)}</p>`:`<button data-reply="${i.id}">Responder à ocorrência</button><label>Enviar evidência da ocorrência<input type="file" accept="image/*" data-incident-photo="${i.id}"></label><div data-incident-preview="${i.id}"></div>${photoMarkup(d.photos.filter(p=>p.incident_id===i.id))}${hub?.admin?`<button data-resolve="${i.id}">Analisar e resolver</button>`:''}`}</div>`).join('')}</section>`:''}${j.state==='approved'&&!hasRating?'<section class="card"><h3>Como foi a experiência?</h3><p>Avaliar é opcional e não muda o repasse.</p><button id="rate">☆ Avaliar</button></section>':''}<div id="rating-form"></div>${d.ratings.length?`<section class="card"><h3>Avaliações</h3>${d.ratings.map(r=>`<p><strong>${r.stars} ☆</strong> ${r.published_at?'Publicada':'Aguardando publicação'}${r.hidden?' · Ocultada por análise':''}<br>${esc(r.comment)}</p>${hub?.admin?`<button data-moderate="${r.author_id}">${r.hidden?'Reexibir':'Analisar conteúdo abusivo'}</button>`:''}`).join('')}</section><div id="moderation-form"></div>`:''}`);
 document.querySelector('#repeat')?.addEventListener('click',()=>requestForm(j.property_id));
 document.querySelector('#change-time')?.addEventListener('click',()=>changeForm(j));
 for(const [selector,approve] of [['#accept-change',true],['#decline-change',false]])document.querySelector(selector)?.addEventListener('click',()=>run('respond_change',{job_id:j.id,approve,proposal_at:j.change_pending.proposed_at},()=>job(j.id)));
 app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>run(b.dataset.action,{job_id:id},()=>job(id)));
 document.querySelector('#activate-routine')?.addEventListener('click',async()=>{try{const q=(await api('quote',{property_id:j.property_id,worker_id:j.target_worker||undefined})).result;showRoutineConfirm(j,q);}catch(e){notice(errorText(e),true);}});
 document.querySelector('#pix')?.addEventListener('click',()=>pixForm(j));
 document.querySelector('#copy-manual-pix')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(d.manual_payment.destination.key);notice('Chave copiada. No seu banco, escolha Pix por chave e confira o nome e o valor.');}catch{notice('Selecione e copie a chave exibida.',true);}});
 document.querySelector('#report-manual-pix')?.addEventListener('click',()=>run('manual_report',{payment_id:d.manual_payment.payment_id},()=>job(j.id)));
 document.querySelector('#copy-pix')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(d.payment.qr_text);notice('Código Pix copiado. Abra seu banco e escolha Pix Copia e Cola.');}catch{notice('Selecione e copie o código exibido.',true);}});
 document.querySelector('#approve')?.addEventListener('click',()=>run('approve',{job_id:id},()=>job(id)));
 document.querySelector('#correction')?.addEventListener('click',()=>problemForm(j,'correction'));
 document.querySelector('#problem').onclick=()=>problemForm(j,'incident');document.querySelector('#cancel')?.addEventListener('click',()=>problemForm(j,'cancel'));
 document.querySelector('#favorite-toggle')?.addEventListener('click',()=>run('favorite',{worker_id:j.worker_id},()=>job(id)));
 app.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>problemForm(j,'reply',b.dataset.reply));app.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>problemForm(j,'resolve',b.dataset.resolve));
 app.querySelectorAll('[data-check]').forEach(b=>b.onchange=async()=>{const value=b.checked,payload={job_id:id,item:Number(b.dataset.check),result:value};await offline('put','result:'+session.user.id+':'+id+':'+payload.item,{action:'result',...payload,user_id:session.user.id}).catch(()=>{});try{await api('result',payload);await offline('delete','result:'+session.user.id+':'+id+':'+payload.item);notice('Item salvo.');}catch(e){notice(errorText(e),true);}await showPending(j);});
 app.querySelectorAll('[data-photo]').forEach(b=>b.onchange=()=>previewPhoto(b,j));
 app.querySelectorAll('[data-incident-photo]').forEach(b=>b.onchange=()=>previewPhoto(b,j));
 document.querySelector('#finish')?.addEventListener('click',async()=>{const pending=(await offline('list')).filter(x=>x.value.user_id===session.user.id&&x.value.job_id===id);if(pending.length){notice('Há fotos ou itens pendentes. Envie antes de terminar.',true);return;}run('submit',{job_id:id},()=>job(id));});
 document.querySelector('#rate')?.addEventListener('click',()=>ratingForm(j,own));
 app.querySelectorAll('[data-moderate]').forEach(b=>b.onclick=()=>{const r=d.ratings.find(x=>x.author_id===b.dataset.moderate);const target=document.querySelector('#moderation-form');target.innerHTML='<form class="card" id="moderation"><h3>Análise de conteúdo</h3><p>Registre o motivo. Não altere a nota nem o comentário da avaliação.</p><label>Justificativa<textarea name="description" required minlength="10"></textarea></label><button class="primary">Salvar decisão</button></form>';document.querySelector('#moderation').onsubmit=e=>{e.preventDefault();run('moderate',{job_id:j.id,author_id:r.author_id,hidden:!r.hidden,description:e.target.elements.description.value},()=>job(j.id));};});await showPending(j);menu();}catch(e){notice(errorText(e),true);}}
function photoMarkup(photos){return photos.length?`<div class="photo-grid">${photos.map(p=>`<a href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="Foto de conferência" loading="lazy"><small>${dt(p.created_at)}</small></a>`).join('')}</div>`:'<p class="small">Ainda sem fotos salvas.</p>';}
function nextStep(j,own,work,payment,manual){if(j.state==='routine')return `<p>A rotina veio do PMS. Ainda não é uma contratação.</p><button id="activate-routine" class="primary">Conferir e solicitar esta faxina</button>`;
 if(j.state==='requested')return '<p>Estamos aguardando uma profissional compatível aceitar o serviço.</p>';
 if(j.state==='awaiting_pix'&&j.snapshot.conditions?.payment_method==='manual_pix'){
  if(!own)return '<p>Aguarde a administração conferir o crédito do Pix. A faxina ainda não está confirmada.</p>';
  const warning=bootstrap.environment==='development'?'<p class="note warning">Validação: não transfira dinheiro real nesta prévia.</p>':'';
  if(manual?.status==='uncertain')return warning+'<p class="note warning">Há uma divergência no pagamento em análise. Não pague outra vez.</p><button data-action="reconcile">Atualizar situação</button>';
  if(manual?.reported_at)return warning+`<p>Você avisou que fez o Pix. A administração vai conferir o crédito no extrato.</p><p>Conferência até ${dt(manual.review_until)}. A faxina ainda não está confirmada.</p><button data-action="reconcile">Atualizar situação</button>`;
  if(manual?.destination&&manual.status==='pending')return warning+`<p>Abra seu banco, escolha Pix por chave e transfira exatamente <strong>${money(manual.amount_cents)}</strong>.</p><p>Confira o destinatário: <strong>${esc(manual.destination.recipient_name)}</strong></p><textarea readonly aria-label="Chave Pix">${esc(manual.destination.key)}</textarea><button id="copy-manual-pix" class="primary">Copiar chave Pix</button><p class="small">Prazo: ${dt(manual.expires_at)}. Chave Pix não é código QR Copia e Cola.</p><button id="report-manual-pix">Já fiz o Pix · Avisar administração</button><p class="small">O aviso não confirma o recebimento. Aguarde a conferência do crédito no extrato.</p>`;
  return warning+`<p>O Pix vai para a conta da administração. O pagamento será conferido manualmente.</p><button id="pix" class="primary" ${hub.financial_ready?'':'disabled'}>Ver chave e valor do Pix</button>${hub.financial_ready?'':'<p>A administração precisa cadastrar e liberar sua chave Pix.</p>'}`;
 }
 if(j.state==='awaiting_pix'){if(!own)return `<p>Aguarde a confirmação do Pix. A faxina ainda não está garantida.</p><p class="small">Prazo para pagamento: ${dt(j.pay_until)}</p>`;return `<p>Depois do pagamento confirmado, a profissional recebe o endereço.</p><p class="small">Prazo: ${dt(j.pay_until)}</p>${payment?.status==='pending'&&payment.qr_text?`<textarea readonly aria-label="Código Pix">${esc(payment.qr_text)}</textarea><button id="copy-pix" class="primary">Copiar código Pix</button><button data-action="reconcile">Conferir pagamento</button>`:payment?.status==='uncertain'?'<p class="note warning">Pagamento em conciliação. Não pague novamente.</p><button data-action="reconcile">Conferir pagamento</button>':`<button id="pix" class="primary" ${hub.financial_ready?'':'disabled'}>Pagar com Pix</button>${hub.financial_ready?'':'<p class="note warning">O Pix das faxinas aguarda liberação do intermediador. Nenhuma cobrança foi criada.</p>'}`}`;}
 if(j.state==='confirmed'&&work)return '<p>Na janela combinada, toque no botão para começar.</p><button data-action="start" class="primary">▶ Começar limpeza</button>';
 if(j.state==='correction'&&work)return '<p>Combine o novo horário se a janela anterior terminou. Comece a correção e envie ao menos uma nova foto.</p><button data-action="start" class="primary">▶ Começar correção</button>';
 if(j.state==='in_progress'||j.state==='correction')return `<p>${work?'Complete os itens e as fotos abaixo.':'A profissional está cuidando do imóvel.'}</p>`;
 if(j.state==='review')return `<p>Confira as fotos. Sem ocorrência aberta, a aprovação ocorre após o prazo combinado.</p><p class="small">Conferência até ${dt(j.review_until)}</p>${own?'<button id="approve" class="primary">✓ Aprovar faxina</button><button id="correction" class="spacer">Solicitar correção</button>':'<p>Você não precisa receber uma avaliação por estrelas para ter o repasse autorizado.</p>'}`;
 return `<p>${stateLabel[j.state]||'Acompanhe o serviço aqui.'}</p>`;}
function showRoutineConfirm(j,q){const box=app.querySelector('.split section:last-child .card');box.innerHTML=`<h3>Confirme as condições</h3>${q.quote_required?'<p>Solicite orçamento administrativo antes de contratar.</p>':`${breakdown(q)}<p class="spacer">${esc(q.service.scope)}</p><p>${esc(q.terms)}</p><label class="check"><input id="routine-terms" type="checkbox">Li o preço, o escopo e as condições</label><button id="routine-confirm" class="primary">Solicitar faxina</button>`}`;document.querySelector('#routine-confirm')?.addEventListener('click',()=>{if(!document.querySelector('#routine-terms').checked){notice('Marque o aceite para solicitar.',true);return;}run('activate_routine',{job_id:j.id,accepted_quote:q,accept_terms:true},()=>job(j.id));});}
function pixForm(j){if(j.snapshot.conditions?.payment_method==='manual_pix'){run('manual_claim',{job_id:j.id},()=>job(j.id));return;}if(!hub.financial_ready){notice(errors.financial_dependency_unavailable,true);return;}const box=app.querySelector('.split section:last-child .card');box.innerHTML=`<form id="pix-form"><h3>Dados para o Pix</h3><p>O PagBank precisa do documento do pagador. Ele não aparece na oferta da faxina.</p>${input('CPF ou CNPJ','tax_id','','text','required inputmode="numeric"')}<button class="primary">Gerar Pix</button></form>`;document.querySelector('#pix-form').onsubmit=e=>{e.preventDefault();run('pix',{job_id:j.id,tax_id:e.target.elements.tax_id.value},()=>job(j.id));};}
async function previewPhoto(input,j){const file=input.files?.[0];if(!file)return;const box=app.querySelector(input.dataset.incidentPhoto?`[data-incident-preview="${input.dataset.incidentPhoto}"]`:`[data-preview="${input.dataset.photo}"]`);try{const photo=await compressPhoto(file);box.innerHTML=`<img class="photo-preview" src="${photo.preview}" alt="Prévia da foto escolhida"><div class="buttons"><button data-send-photo class="primary">Enviar esta foto</button><button data-retake>Escolher outra foto</button></div>`;box.querySelector('[data-retake]').onclick=()=>{input.value='';box.innerHTML='';input.click();};box.querySelector('[data-send-photo]').onclick=async()=>{const {preview,...data}=photo;const p={...data,job_id:j.id,item:input.dataset.incidentPhoto?-1:Number(input.dataset.photo),incident_id:input.dataset.incidentPhoto,upload_id:crypto.randomUUID(),user_id:session.user.id};await offline('put','upload:'+p.user_id+':'+p.upload_id,{action:'upload',...p});box.innerHTML='<p class="pending">Foto salva no aparelho. Enviando…</p>';await retryPending('upload:'+p.user_id+':'+p.upload_id,p,j);};}catch(e){notice(errorText(e),true);}}
async function retryPending(key,p,j){try{await api(p.action||'upload',p);await offline('delete',key);notice('Progresso enviado e salvo.');await job(j.id);}catch(e){notice(errorText(e),true);await showPending(j);}}
async function showPending(j){const target=document.querySelector('#pending');if(!target)return;try{const pending=(await offline('list')).filter(x=>x.value.user_id===session.user.id&&x.value.job_id===j.id);target.innerHTML=pending.length?`<div class="pending spacer"><strong>${pending.length} envio(s) pendente(s)</strong><p>Continuam salvos no aparelho. Tente de novo quando houver conexão.</p>${pending.map(p=>`<button data-retry="${esc(p.key)}">Reenviar ${p.value.action==='result'?'item':'foto'} ${Number(p.value.item)+1}</button>`).join('')}</div>`:'';target.querySelectorAll('button').forEach(b=>b.onclick=()=>{b.disabled=true;const p=pending.find(x=>x.key===b.dataset.retry);retryPending(p.key,p.value,j);});}catch{target.innerHTML='<p class="note warning">Não foi possível usar o armazenamento do aparelho. Mantenha esta tela aberta até salvar os envios.</p>';}}
function problemForm(j,action,incident_id){const target=document.querySelector('#incident-form');target.innerHTML=`<form class="card" id="problem-form"><h3>${{incident:'Relatar problema',cancel:'Pedir cancelamento',correction:'O que precisa corrigir?',reply:'Sua resposta',resolve:'Análise administrativa'}[action]}</h3><label>Conte com suas palavras<textarea name="description" required minlength="5" maxlength="4000"></textarea></label>${action==='incident'?'<label>Tipo<select name="severity"><option value="normal">Problema com o serviço</option><option value="serious">Situação grave — pedir análise urgente</option></select></label>':''}${action==='reply'?`<label>Foto de evidência<select name="photo_id"><option value="">Sem foto</option>${activeJob.photos.map(p=>`<option value="${p.id}">Foto de ${dt(p.created_at)}</option>`).join('')}</select></label>`:''}${action==='resolve'?'<label>Decisão<select name="decision"><option value="no_change">Registrar análise sem alterar serviço</option><option value="resume">Liberar a continuidade após combinar</option><option value="approve">Aprovar serviço após analisar evidências</option><option value="refund">Autorizar devolução integral para processamento</option></select></label>':''}<p class="small">Problemas são analisados com evidências e resposta das duas partes. Relatar um problema não desconta valores automaticamente.</p><button class="primary">Salvar ${action==='reply'?'resposta':'pedido'}</button></form>`;target.scrollIntoView({block:'start'});document.querySelector('#problem-form').onsubmit=e=>{e.preventDefault();run(action,{job_id:j.id,incident_id,...Object.fromEntries(new FormData(e.target))},()=>job(j.id));};}
function ratingForm(j,own){const target=document.querySelector('#rating-form');target.innerHTML=`<form id="rating" class="card"><h3>Como foi a experiência?</h3><fieldset><legend>Sua nota</legend><div class="stars">${[1,2,3,4,5].map(n=>`<label><input name="stars" type="radio" value="${n}" required>${n} ☆</label>`).join('')}</div></fieldset><details><summary>Avaliar detalhes (opcional)</summary>${(own?[['cleanliness','Limpeza'],['punctuality','Pontualidade'],['care','Cuidado']]:[['respect','Respeito'],['instructions','Clareza das instruções'],['conditions','Condições do imóvel']]).map(([key,label])=>`<label>${label}<select name="indicator_${key}"><option value="">Não avaliar</option>${options([1,2,3,4,5].map(n=>[String(n),String(n)]))}</select></label>`).join('')}</details><label>Comentário (opcional)<textarea name="comment" maxlength="2000"></textarea></label><p class="small">As avaliações ficam públicas quando os dois lados avaliarem ou após o prazo combinado.</p><button class="primary">Enviar avaliação</button></form>`;document.querySelector('#rating').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),indicators=Object.fromEntries(Object.entries(f).filter(([k,v])=>k.startsWith('indicator_')&&v).map(([k,v])=>[k.slice(10),Number(v)]));run('rate',{job_id:j.id,stars:Number(f.stars),comment:f.comment,indicators},()=>job(j.id));};target.scrollIntoView({block:'start'});}
async function load(target='home',draw=true){if(!session){landing();return;}try{hub=await api('hub');if(!adminPage)hub.properties=hub.properties.filter(p=>p.owner_id===session.user.id);view=target;menu();if(draw)go(target);}catch(e){notice(errorText(e),true);app.setAttribute('aria-busy','false');}}
async function go(target){notice('');if(adminPage&&['home','services'].includes(target)){if(target==='services')adminTab='jobs';target='admin';}if(appMode==='owner'&&target==='offers')target='home';if(appMode==='worker'&&['request','properties','directory'].includes(target))target='home';if(target==='admin'&&!adminPage&&hub?.admin){location.href=appPaths.admin;return;}if(target==='prices'){prices();return;}if(!session){target==='home'?landing():login();return;}if(!hub){await load(target);return;}view=target;switch(target){case 'home':home();break;case 'profile':profile();break;case 'properties':properties();break;case 'services':services();break;case 'directory':directory();break;case 'offers':offers();break;case 'request':requestForm();break;case 'admin':if(!hub.admin){if(adminPage){render('<h1>Acesso restrito</h1><p>Esta conta não tem autorização para administrar as faxinas.</p><a class="button" href="/faxinas.html">Voltar aos aplicativos</a>');menu();}else home();notice(errors.cleaning_admin_required,true);return;}const {renderAdmin}=await import('./faxinas-admin.js');renderAdmin({app,hub,api,run,load,esc,money,input,checked,options,notice,dt,stateLabel,listScope:session.user.id,tab:adminTab,setTab:v=>adminTab=v});menu();break;default:home();}}
async function start(){try{sb=window.supabase?.createClient(C.supabaseUrl,C.supabaseKey,C.authOptions);if(!sb)throw Error('unavailable');bootstrap=await api('bootstrap');if(bootstrap.environment==='development'){const e=document.querySelector('#environment');e.hidden=false;e.textContent='Ambiente de validação · serviços e dinheiro reais não estão liberados';}session=(await sb.auth.getSession()).data.session;document.querySelector('#account').onclick=()=>session?go('profile'):login();if(session){await load(adminPage?'admin':'home');let pending;try{pending=JSON.parse(sessionStorage.getItem('cleaning_confirmation'));}catch{}sessionStorage.removeItem('cleaning_confirmation');if(!hub?.member&&pending&&!adminPage)profile(pending.role||'owner');const id=new URLSearchParams(location.search).get('job');if(id)await job(id);}else {let pending;try{pending=JSON.parse(sessionStorage.getItem('cleaning_confirmation'));}catch{}pending?.email&&!adminPage?confirmation(pending.email,pending.role):adminPage?login():landing();}}catch(e){render('<section class="card"><h1>Vamos tentar de novo?</h1><p>Não foi possível carregar agora. Confira sua conexão.</p><button id="reload" class="primary">Tentar novamente</button></section>');document.querySelector('#reload').onclick=()=>start();notice(errorText(e),true);}}
start();

function changeForm(j){const target=document.querySelector('#change-form');target.innerHTML=`<form class="card" id="change-schedule"><h3>Combinar novo horário</h3><p>Preço e escopo permanecem os mesmos. Os dois lados precisam concordar.</p>${input('Dia','date','','date','required')}${input('Pode começar às','time','09:00','time','required')}${input('Terminar até','until','13:00','time','required')}<label>Motivo<textarea name="description" required minlength="5"></textarea></label><button class="primary">Propor horário</button></form>`;document.querySelector('#change-schedule').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));run('propose_change',{job_id:j.id,starts_at:new Date(f.date+'T'+f.time+':00-03:00').toISOString(),ends_at:new Date(f.date+'T'+f.until+':00-03:00').toISOString(),description:f.description},()=>job(j.id));};target.scrollIntoView({block:'start'});}
